pub struct Slot {
    pub kind: Kind,
    pub id: u64,
    pub txid: u32,
    pub lease_end: u64,
}

Kind.kernel_code:
pub enum Kind {
    Free,
    Offered,
    Assigned,
}

answer_fits.kernel_code:
pub fn answer_fits(received: usize, buffer: usize, question_len: usize) -> bool {
    let end = DNS_HEADER_SIZE + question_len;
    end <= received && end + ANSWER_SIZE <= buffer
}

request.kernel_code:
pub fn request(slots: &mut [Slot], cid: u64, txid: u32, now: u64, new_end: u64) -> Option<usize> {
    let mut i: usize = 0;
    while i < slots.len() {
        let s = slots[i];
        let hit = match s.kind {
            Kind::Offered => {
                if s.id == cid && s.txid == txid {
                    true
                } else {
                    false
                }
            }
            Kind::Assigned => {
                if s.id == cid && s.txid == txid && now < s.lease_end {
                    true
                } else {
                    false
                }
            }
            Kind::Free => false,
        };
        if hit {
            slots[i] = Slot { kind: Kind::Assigned, id: cid, txid, lease_end: new_end };
            return Some(i);
        }
        i += 1;
    }
    None
}

discover.kernel_code:
pub fn discover(slots: &mut [Slot], cid: u64, txid: u32, now: u64) -> Option<usize> {
    let mut first_offered: Option<usize> = None;
    let mut i: usize = 0;
    while i < slots.len() {
        let s = slots[i];
        let usable = match s.kind {
            Kind::Offered => {
                if s.id != cid {
                    first_offered = Some(i);
                    false
                } else {
                    true
                }
            }
            // (explicit ifs: the same, and Bool results Aeneas types right)
            Kind::Assigned => {
                if s.id == cid {
                    true
                } else if now >= s.lease_end {
                    true
                } else {
                    false
                }
            }
            Kind::Free => true,
        };
        if usable {
            slots[i] = Slot { kind: Kind::Offered, id: cid, txid, lease_end: s.lease_end };
            return Some(i);
        }
        i += 1;
    }
    match first_offered {
        Some(j) => {
            let le = slots[j].lease_end;
            slots[j] = Slot { kind: Kind::Offered, id: cid, txid, lease_end: le };
            Some(j)
        }
        None => None,
    }
}
